export const HINDI_MAP: Record<string, string> = {};

const charIndex: Record<string, { key: KeyDef; shift: boolean }> = {};

const EN_SHIFT_MAP: Record<string, string> = {
  '\`': '~', '1': '!', '2': '@', '3': '#', '4': '$', '5': '%', '6': '^', '7': '&', '8': '*', '9': '(', '0': ')', '-': '_', '=': '+',
  '[': '{', ']': '}', '\\\\': '|', ';': ':', "'": '"', ',': '<', '.': '>', '/': '?'
};

// First pass: unshifted keys get absolute priority
for (const row of keyboardRows) {
  for (const key of row) {
    if (key.en.length === 1 && key.hi) {
      HINDI_MAP[key.en.toLowerCase()] = key.hi;
    }
    if (key.en.length === 1 && key.shift) {
      if (key.en.match(/[a-zA-Z]/)) {
        HINDI_MAP[key.en.toUpperCase()] = key.shift;
      } else {
        const mappedShift = EN_SHIFT_MAP[key.en];
        if (mappedShift !== undefined) {
          HINDI_MAP[mappedShift] = key.shift;
        }
      }
    }
    if (key.hi && !charIndex[key.hi]) {
      charIndex[key.hi] = { key, shift: false };
    }
  }
}

// Second pass: shift keys only if not already mapped to an unshifted key
for (const row of keyboardRows) {
  for (const key of row) {
    if (key.shift) {
      const existing = charIndex[key.shift];
      const isExistingLetter = existing && existing.key.en.match(/[a-zA-Z]/);
      const isNewLetter = key.en.match(/[a-zA-Z]/);

      // Map if it doesn't exist, OR if the new key is a letter and the old key is a symbol/number
      if (!existing || (!isExistingLetter && isNewLetter)) {
        charIndex[key.shift] = { key, shift: true };
      }
    }
  }
}

export function lookupChar(ch: string) {
  return charIndex[ch];
}

