  { slug: 'ch43', title: 'Word Practice', hindiTitle: 'अभ्यास ७', description: 'Mixed', level: 'शुरुआती', keys: 'अभ्यास', minutes: 3, text: 'चूक रस अमर समय हल दाम हक राही सिरे िपता कसर रख कर रंक िकया हंस कह से महल सही सहर समग्र केस हार उग्र सजा राज रही इनाम सिर चंद्र यार एकता कार सब्र नाम आग सार गाल चना रहे लाल रही सही अमर चंद्र सिर समय गाल िपता रख इनाम चूक कसर रंक िकया यार उग्र हक कह समग्र लाल केस सजा सब्र दाम कर सिरे एकता चना राही हल हंस से रस कार हार सहर आग रहे नाम राज सार महल कार सिर इनाम िकया सार सजा राही रहे महल कह रंक कसर नाम आग हक केस' },
  { slug: 'ch44', title: 'Word Practice', hindiTitle: 'अभ्यास ८', description: 'Mixed', level: 'शुरुआती', keys: 'अभ्यास', minutes: 3, text: 'नाम िपता सिरे कह लाल रही से िकया हक चूक इनाम कसर सार रस चंद्र चना हंस उग्र कार राज यार सब्र हार दाम एकता अमर रख सहर आग रंक रहे सही सिर समग्र राही कर हल केस महल सजा समय गाल हल महल कसर सिरे से अमर चना दाम हंस हार समग्र समय उग्र यार राज रंक सब्र िपता सार लाल कर हक सजा सहर एकता कार सही आग इनाम चूक सिर िकया रख गाल राही रस नाम केस रही रहे कह चंद्र चंद्र एकता आग से सब्र सिरे कसर कार महल िकया यार हल रख हक सजा हंस' },
  { slug: 'ch45', title: 'Word Practice', hindiTitle: 'अभ्यास ९', description: 'Mixed', level: 'शुरुआती', keys: 'अभ्यास', minutes: 3, text: 'चंद्र हंस गाल सही समग्र एकता इनाम सिरे कह महल केस सहर कार कसर लाल आग हक दाम से सार हार िपता समय नाम चना रहे कर िकया हल यार राज रख रंक सब्र उग्र सिर रस राही रही चूक अमर सजा सही समग्र िपता इनाम केस हक राज कार हल सिर कह दाम राही समय सब्र कर गाल चंद्र यार रहे चना रस रही सिरे सार आग अमर सहर एकता सजा महल चूक हार लाल िकया रंक रख से हंस नाम कसर उग्र सजा चूक समय सार कसर सही लाल िपता रहे इनाम रख केस राही आग रही हल' }
